func (l *Limiter) AllowN(n int64) bool {
    if l == nil || n <= 0 { return false }
    l.mu.Lock()
    defer l.mu.Unlock()
    if l.capacity <= 0 || l.every <= 0 || l.clock == nil || n > l.capacity { return false }
